INSERT INTO assessments (id, teacher_id, class_id, instrument_id, instrument_snapshot_json, participant_ids_json, date, status, finalized_at, reopened_at, created_at, updated_at) VALUES ('demo-assessment-1', 'demo-teacher', 'demo-class-7a', 'tksi-terpadu', '{"id":"tksi-terpadu","slug":"tksi-terpadu","version":1,"group":"tksi","name":"TKSI — Instrumen Terpadu","description":"Menggabungkan lima butir tes TKSI dan penilaian sikap pelaksanaan tes untuk memperoleh nilai kebugaran menyeluruh.","purpose":"Memberikan gambaran kebugaran jasmani menyeluruh dengan mempertimbangkan hasil tes produk dan sikap saat pelaksanaan.","procedure":["Siapkan alat dan lokasi sesuai kebutuhan butir tes.","Lakukan pemanasan 5–10 menit sebelum pelaksanaan tes.","Jelaskan teknik gerak dan aturan tes kepada peserta didik.","Lakukan tes satu per satu atau dalam kelompok kecil dengan pengawasan guru.","Catat hasil terbaik dan hentikan tes bila peserta didik mengalami keluhan fisik.","Laksanakan seluruh butir tes TKSI: lari 1000 m, sit-up, lari 50 m, shuttle run, dan loncat tegak.","Amati sikap peserta didik selama pelaksanaan tes.","Masukkan seluruh hasil ke aplikasi untuk memperoleh nilai proses dan produk."],"indicators":[{"id":"sikap-pelaksanaan","name":"Sikap Pelaksanaan Tes","description":"Kedisiplinan, sportivitas, dan usaha maksimal selama mengikuti rangkaian tes.","unit":"skor","kind":"process","weight":0.2,"higherIsBetter":true,"required":true,"rubricBands":[{"min":0,"max":55,"points":50,"label":"Perlu Bimbingan","description":"Teknik dasar belum dikuasai, banyak kesalahan dan tidak konsisten."},{"min":55,"max":70,"points":65,"label":"Cukup","description":"Teknik dasar dikuasai sebagian, masih ada kesalahan yang terlihat."},{"min":70,"max":85,"points":80,"label":"Baik","description":"Teknik dasar dikuasai dengan baik dan konsisten pada sebagian besar percobaan."},{"min":85,"max":100,"points":95,"label":"Sangat Baik","description":"Teknik dikuasai sangat baik, efisien, konsisten, dan dapat diterapkan dalam permainan."}]},{"id":"lari-1000m","name":"Waktu Lari 1000 m","description":"Waktu tempuh lari 1000 meter dalam detik; semakin kecil semakin baik.","unit":"detik","kind":"product","weight":0.16,"higherIsBetter":false,"required":true,"normTable":[{"sex":"L","ageMin":7,"ageMax":9,"points":[{"raw":300,"score":100},{"raw":375,"score":85},{"raw":450,"score":70},{"raw":600,"score":50},{"raw":750,"score":25}]},{"sex":"P","ageMin":7,"ageMax":9,"points":[{"raw":375,"score":100},{"raw":450,"score":85},{"raw":525,"score":70},{"raw":675,"score":50},{"raw":825,"score":25}]},{"sex":"L","ageMin":10,"ageMax":12,"points":[{"raw":272.73,"score":100},{"raw":340.91,"score":85},{"raw":409.09,"score":70},{"raw":545.45,"score":50},{"raw":681.82,"score":25}]},{"sex":"P","ageMin":10,"ageMax":12,"points":[{"raw":340.91,"score":100},{"raw":409.09,"score":85},{"raw":477.27,"score":70},{"raw":613.64,"score":50},{"raw":750,"score":25}]},{"sex":"L","ageMin":13,"ageMax":15,"points":[{"raw":255.32,"score":100},{"raw":319.15,"score":85},{"raw":382.98,"score":70},{"raw":510.64,"score":50},{"raw":638.3,"score":25}]},{"sex":"P","ageMin":13,"ageMax":15,"points":[{"raw":319.15,"score":100},{"raw":382.98,"score":85},{"raw":446.81,"score":70},{"raw":574.47,"score":50},{"raw":702.13,"score":25}]},{"sex":"L","ageMin":16,"ageMax":18,"points":[{"raw":240,"score":100},{"raw":300,"score":85},{"raw":360,"score":70},{"raw":480,"score":50},{"raw":600,"score":25}]},{"sex":"P","ageMin":16,"ageMax":18,"points":[{"raw":300,"score":100},{"raw":360,"score":85},{"raw":420,"score":70},{"raw":540,"score":50},{"raw":660,"score":25}]}]},{"id":"situp-60s","name":"Sit-up 60 Detik","description":"Jumlah sit-up benar dalam 60 detik; semakin banyak semakin baik.","unit":"repetisi","kind":"product","weight":0.16,"higherIsBetter":true,"required":true,"normTable":[{"sex":"L","ageMin":7,"ageMax":9,"points":[{"raw":8,"score":25},{"raw":16,"score":50},{"raw":28,"score":70},{"raw":36,"score":85},{"raw":44,"score":100}]