INSERT INTO assessments (id, teacher_id, class_id, instrument_id, instrument_snapshot_json, participant_ids_json, date, status, finalized_at, reopened_at, created_at, updated_at) VALUES ('demo-assessment-2', 'demo-teacher', 'demo-class-8b', 'sepak-bola', '{"id":"sepak-bola","slug":"sepak-bola","version":1,"group":"bola_besar","name":"Sepak Bola — Teknik Dasar","description":"Instrumen penilaian proses keterampilan teknik dasar sepak bola: passing, dribbling, shooting, dan sikap.","purpose":"Menilai kualitas proses keterampilan bermain sepak bola secara terstruktur dan berbasis rubrik.","procedure":["Siapkan lapangan dan bola yang sesuai untuk sepak bola.","Lakukan pemanasan dan jelaskan kriteria penilaian kepada peserta didik.","Amati setiap indikator teknik saat peserta melakukan gerak dasar dalam situasi permainan.","Beri skor 0–100 untuk setiap indikator sesuai rubrik, bukan berdasarkan hasil akhir pertandingan.","Uji passing: peserta melakukan passing dari jarak 5 meter sebanyak 5 kali.","Uji dribbling: peserta menggiring bola melewati 5 cone sejauh 20 meter.","Uji shooting: peserta melakukan tembakan ke gawang dari jarak 10 meter sebanyak 3 kali."],"indicators":[{"id":"passing","name":"Passing","description":"Ketepatan, kekuatan, dan sikap tubuh saat mengumpan bola.","unit":"skor","kind":"process","weight":0.3,"higherIsBetter":true,"required":true,"rubricBands":[{"min":0,"max":55,"points":50,"label":"Perlu Bimbingan","description":"Teknik dasar belum dikuasai, banyak kesalahan dan tidak konsisten."},{"min":55,"max":70,"points":65,"label":"Cukup","description":"Teknik dasar dikuasai sebagian, masih ada kesalahan yang terlihat."},{"min":70,"max":85,"points":80,"label":"Baik","description":"Teknik dasar dikuasai dengan baik dan konsisten pada sebagian besar percobaan."},{"min":85,"max":100,"points":95,"label":"Sangat Baik","description":"Teknik dikuasai sangat baik, efisien, konsisten, dan dapat diterapkan dalam permainan."}]},{"id":"dribbling","name":"Dribbling","description":"Kontrol bola, perubahan arah, dan kecepatan menggiring bola.","unit":"skor","kind":"process","weight":0.25,"higherIsBetter":true,"required":true,"rubricBands":[{"min":0,"max":55,"points":50,"label":"Perlu Bimbingan","description":"Teknik dasar belum dikuasai, banyak kesalahan dan tidak konsisten."},{"min":55,"max":70,"points":65,"label":"Cukup","description":"Teknik dasar dikuasai sebagian, masih ada kesalahan yang terlihat."},{"min":70,"max":85,"points":80,"label":"Baik","description":"Teknik dasar dikuasai dengan baik dan konsisten pada sebagian besar percobaan."},{"min":85,"max":100,"points":95,"label":"Sangat Baik","description":"Teknik dikuasai sangat baik, efisien, konsisten, dan dapat diterapkan dalam permainan."}]},{"id":"shooting","name":"Shooting","description":"Akurasi, kekuatan, dan teknik menendang ke arah gawang.","unit":"skor","kind":"process","weight":0.25,"higherIsBetter":true,"required":true,"rubricBands":[{"min":0,"max":55,"points":50,"label":"Perlu Bimbingan","description":"Teknik dasar belum dikuasai, banyak kesalahan dan tidak konsisten."},{"min":55,"max":70,"points":65,"label":"Cukup","description":"Teknik dasar dikuasai sebagian, masih ada kesalahan yang terlihat."},{"min":70,"max":85,"points":80,"label":"Baik","description":"Teknik dasar dikuasai dengan baik dan konsisten pada sebagian besar percobaan."},{"min":85,"max":100,"points":95,"label":"Sangat Baik","description":"Teknik dikuasai sangat baik, efisien, konsisten, dan dapat diterapkan dalam permainan."}]},{"id":"sikap","name":"Sikap dan Sportivitas","description":"Kedisiplinan, kerja sama, dan sportivitas selama asesmen.","unit":"skor","kind":"process","weight":0.2,"higherIsBetter":true,"required":true,"rubricBands":[{"min":0,"max":55,"points":50,"label":"Perlu Bimbingan","description":"Teknik dasar belum dikuasai, banyak kesalahan dan tidak konsisten."},{"min":55,"max":70,"points":65,"label":"Cukup","description":"Teknik dasar dikuasai sebagian, masih ada kesalahan yang terlihat."},{"min":70,"max":85,"points":80,"label":"Baik","description":"Teknik dasar dikuasai dengan baik dan konsisten pada sebagian besar percobaan."},{"min":85,"max":100,"points":95,"label":"Sangat Baik","description":"Teknik dikuasai sangat baik, efisien, konsisten, dan dapat diterapkan dalam permainan."}]}],"categoryThresholds":[{"minScore":0,"maxScore":60,"category":"perlu_bimbingan","label":"Perlu Bimbingan"},{"minScore":60,"maxScore":75,"category":"cukup","label":"Cukup"},{"minScore":75,"maxScore":90,"category":"baik","label":"Baik"},{"minScore":90,"maxScore":100,"category":"sangat_baik","label":"Sangat Baik"}],"sources":[{"title":"Panduan Penilaian oleh Pendidik dan Satuan Pendidikan untuk SMP","author":"Direktorat Jenderal Pendidikan Dasar dan Menengah","year":2017,"publisher":"Kementerian Pendidikan dan Kebudayaan","url":"https://repositori.kemdikbud.go.id","note":"Rubrik proses dan kriteria ketuntasan ranah psikomotor."},{"title":"World Athletics Kids'' Athletics — Teaching Manual","author":"World Athletics","year":2019,"publisher":"World Athletics","url":"https://worldathletics.org","note":"Prinsip teknik dasar dan penilaian nomor atletik anak."}],"assessesProcess":true,"assessesProduct":false,"scoringFormula":{"type":"weighted_sum"}}', '["demo-student-8-01","demo-student-8-02","demo-student-8-03","demo-student-8-04","demo-student-8-05","demo-student-8-06","demo-student-8-07","demo-student-8-08","demo-student-8-09","demo-student-8-10","demo-student-8-11","demo-student-8-12","demo-student-8-13","demo-student-8-14","demo-student-8-15","demo-student-8-16","demo-student-8-17","demo-student-8-18","demo-student-8-19","demo-student-8-20","demo-student-8-21","demo-student-8-22","demo-student-8-23","demo-student-8-24","demo-student-8-25","demo-student-8-26","demo-student-8-27","demo-student-8-28","demo-student-8-29","demo-student-8-30"]', '2026-10-05', 'finalized', '2026-10-05T08:00:00.000Z', NULL, '2026-10-05T08:00:00.000Z', '2026-10-05T08:00:00.000Z') ON CON