"P","ageMin":13,"ageMax":15,"points":[{"raw":4.7,"score":25},{"raw":9.4,"score":50},{"raw":16.92,"score":70},{"raw":22.56,"score":85},{"raw":28.2,"score":100}]},{"sex":"L","ageMin":16,"ageMax":18,"points":[{"raw":8,"score":25},{"raw":16,"score":50},{"raw":26,"score":70},{"raw":33,"score":85},{"raw":40,"score":100}]},{"sex":"P","ageMin":16,"ageMax":18,"points":[{"raw":5,"score":25},{"raw":10,"score":50},{"raw":18,"score":70},{"raw":24,"score":85},{"raw":30,"score":100}]}]}],"categoryThresholds":[{"minScore":0,"maxScore":60,"category":"perlu_bimbingan","label":"Perlu Bimbingan"},{"minScore":60,"maxScore":75,"category":"cukup","label":"Cukup"},{"minScore":75,"maxScore":90,"category":"baik","label":"Baik"},{"minScore":90,"maxScore":100,"category":"sangat_baik","label":"Sangat Baik"}],"sources":[{"title":"Buku Pedoman Tes Kebugaran Jasmani","author":"Direktorat Jenderal Pendidikan Jasmani","year":2020,"publisher":"Kementerian Pendidikan dan Kebudayaan","url":"https://repositori.kemdikbud.go.id","note":"Komponen kebugaran jasmani dan tabel norma hasil adaptasi."},{"title":"ACSM Guidelines for Exercise Testing and Prescription (10th ed.)","author":"American College of Sports Medicine","year":2018,"publisher":"Wolters Kluwer","url":"https://www.acsm.org","note":"Landasan komponen kebugaran jasmani terkait kesehatan."}],"assessesProcess":false,"assessesProduct":true,"scoringFormula":{"type":"weighted_sum"}}', '["demo-student-7-01","demo-student-7-02","demo-student-7-03","demo-student-7-04","demo-student-7-05","demo-student-7-06","demo-student-7-07","demo-student-7-08","demo-student-7-09","demo-student-7-10","demo-student-7-11","demo-student-7-12","demo-student-7-13","demo-student-7-14","demo-student-7-15","demo-student-7-16","demo-student-7-17","demo-student-7-18","demo-student-7-19","demo-student-7-20","demo-student-7-21","demo-student-7-22","demo-student-7-23","demo-student-7-24","demo-student-7-25","demo-student-7-26","demo-student-7-27","demo-student-7-28","demo-student-